from datetime import datetime, timezone
import json
import os
from pathlib import Path
import re
import sys
import time
import uuid

ROOT = Path('/home/r/dev/minor/stackd')
sys.path.insert(0, str(ROOT / 'scripts/aws'))
from aws_cli import run, result

OUT = ROOT / 'testdata/aws/stepfunctions/dataflow_execution.json'
CAP = json.loads(OUT.read_text())
PREFIX = 'sd-sfn-flow-' + uuid.uuid4().hex[:10]
ROLE = PREFIX + '-role'
ROLE_ARN = 'arn:aws:iam::000000000000:role/' + ROLE
MACHINES = {key: 'arn:aws:states:us-west-2:000000000000:stateMachine:' + PREFIX + '-' + key for key in CAP['definitions']}
ENV = dict(os.environ, AWS_REGION='us-west-2', AWS_DEFAULT_REGION='us-west-2', AWS_MAX_ATTEMPTS='1', AWS_PAGER='', AWS_IGNORE_CONFIGURED_ENDPOINT_URLS='true')
for key in list(ENV):
    if key.startswith('AWS_ENDPOINT_URL'):
        ENV.pop(key)
CAP['started_at'] = datetime.now(timezone.utc).isoformat()
CAP['sources'].append({'path': __file__, 'content': Path(__file__).read_text()})
CAP['sources'].append({'path': 'scripts/aws/aws_cli.py', 'content': (ROOT / 'scripts/aws/aws_cli.py').read_text()})
CAP['owned_resources'] = {'prefix': PREFIX, 'role_name': ROLE, 'role_arn': ROLE_ARN, 'state_machines': MACHINES}
CAP['execution_arns'] = []
created_machines = []
role_created = False
started = time.monotonic()


def save():
    OUT.write_text(json.dumps(CAP, indent=2) + '\n')


def call(label, operation, parameters, service='stepfunctions'):
    before = time.time()
    process = run(service, operation, parameters, ENV, options=['--debug', '--no-paginate', '--cli-connect-timeout', '8', '--cli-read-timeout', '25'], timeout=35)
    value = result(process, debug=True)
    if value['code'] == 'CLIError':
        raise RuntimeError('CLI or transport failure for ' + label + '; diagnostics not persisted')
    ids = re.findall(r'<RequestId>([^<]+)</RequestId>', process.stderr)
    for line in process.stderr.splitlines():
        if 'Response headers: ' in line:
            try:
                headers = ast.literal_eval(line.split('Response headers: ', 1)[1])
                ids.extend(v for k, v in headers.items() if k.lower() in ('x-amzn-requestid', 'x-amz-request-id'))
            except (ValueError, SyntaxError):
                pass
        if line.startswith(("b'{", 'b"{')):
            try:
                value['output'] = json.loads(ast.literal_eval(line))
            except (ValueError, SyntaxError):
                pass
    value['request_id'] = ids[-1] if ids else None
    value.setdefault('output', {})
    CAP['observations'].append({'label': label, 'service': service, 'operation': operation, 'input': parameters, 'request_started_ms': round(before * 1000), 'request_finished_ms': round(time.time() * 1000), 'result': value})
    save()
    return value


def require(label, operation, parameters, service='stepfunctions'):
    value = call(label, operation, parameters, service)
    if value['code'] != 'Success':
        raise RuntimeError(label + ': ' + value['code'])
    return value['output']


def compact(value):
    return json.dumps(value, separators=(',', ':'))


def deadline():
    if time.monotonic() - started > CAP['protocol']['capture_wall_seconds']:
        raise RuntimeError('Capture wall-time bound reached')


try:
    actor = require('identity', 'get-caller-identity', {}, 'sts')
    CAP['actor'] = actor
    if actor['Account'] != CAP['caller_account'] or actor['Arn'] != 'arn:aws:iam::000000000000:user/Delegated':
        raise RuntimeError('Unexpected native identity')
    for case in CAP['validation_cases']:
        definition = CAP['definitions'][case['definition_ref']] if 'definition_ref' in case else case['definition']
        observed = require('validate-' + case['name'], 'validate-state-machine-definition', {'definition': compact(definition), 'type': 'STANDARD', 'severity': 'WARNING'})
        case['validation_result'] = observed['result']
        if 'definition_ref' in case and observed['result'] != 'OK':
            raise RuntimeError('Runnable definition rejected: ' + case['name'])
    absent = call('preflight-role-absence', 'get-role', {'RoleName': ROLE}, 'iam')
    if absent['code'] != 'NoSuchEntity':
        raise RuntimeError('Owned role name is not absent')
    for key, arn in MACHINES.items():
        absent = call('preflight-' + key + '-absence', 'describe-state-machine', {'stateMachineArn': arn})
        if absent['code'] != 'StateMachineDoesNotExist':
            raise RuntimeError('Owned machine name is not absent')
    trust = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': {'Service': 'states.amazonaws.com'}, 'Action': 'sts:AssumeRole', 'Condition': {'StringEquals': {'aws:SourceAccount': CAP['caller_account']}}}]}
    require('create-role', 'create-role', {'RoleName': ROLE, 'AssumeRolePolicyDocument': compact(trust)}, 'iam')
    role_created = True
    for key, definition in CAP['definitions'].items():
        require('create-' + key, 'create-state-machine', {'name': PREFIX + '-' + key, 'definition': compact(definition), 'roleArn': ROLE_ARN, 'type': 'STANDARD'})
        created_machines.append(key)
    time.sleep(3)
    for case in CAP['test_state_cases']:
        deadline()
        parameters = {'definition': compact(case['definition']), 'input': compact(case['input']), 'inspectionLevel': 'DEBUG', 'roleArn': ROLE_ARN}
        if 'variables' in case:
            parameters['variables'] = compact(case['variables'])
        value = call('test-' + case['name'], 'test-state', parameters)
        CAP['outcomes'][case['name']] = {'kind': 'TestState', 'observation': 'test-' + case['name'], 'admission_code': value['code'], 'status': value['output'].get('status'), 'error': value['output'].get('error'), 'output': value['output'].get('output')}
        print(case['name'] + ': ' + value['code'] + '/' + str(value['output'].get('status')), flush=True)
    for case in CAP['execution_cases']:
        deadline()
        value = require('start-' + case['name'], 'start-execution', {'stateMachineArn': MACHINES[case['machine']], 'name': case['name'], 'input': compact(case['input'])})
        arn = value['executionArn']
        CAP['execution_arns'].append(arn)
        last = None
        for poll in range(12):
            last = require('describe-' + case['name'] + '-' + str(poll), 'describe-execution', {'executionArn': arn})
            if last['status'] != 'RUNNING':
                break
            time.sleep(1)
        if last['status'] == 'RUNNING':
            require('bound-stop-' + case['name'], 'stop-execution', {'executionArn': arn, 'error': 'OwnedProbe.BoundedStop'})
            last = require('bounded-' + case['name'], 'describe-execution', {'executionArn': arn})
        history = require('history-' + case['name'], 'get-execution-history', {'executionArn': arn, 'includeExecutionData': True, 'maxResults': 1000})
        if 'nextToken' in history:
            raise RuntimeError('History exceeded bounded one-page fixture size')
        CAP['outcomes'][case['name']] = {'kind': 'Execution', 'execution_arn': arn, 'description_label': CAP['observations'][-2]['label'], 'history_label': 'history-' + case['name'], 'status': last['status'], 'output': last.get('output'), 'error': last.get('error'), 'cause': last.get('cause'), 'event_count': len(history['events'])}
        if case['name'] == 'nested-branches-first':
            require('history-nested-no-data', 'get-execution-history', {'executionArn': arn, 'includeExecutionData': False, 'maxResults': 1000})
            require('history-nested-reverse', 'get-execution-history', {'executionArn': arn, 'reverseOrder': True, 'includeExecutionData': True, 'maxResults': 1000})
        print(case['name'] + ': ' + last['status'], flush=True)
        save()
except BaseException as error:
    CAP['probe_error'] = type(error).__name__ + ': ' + str(error)
    save()
    raise
finally:
    cleanup_started = time.monotonic()
    for index, arn in enumerate(CAP['execution_arns']):
        last = call('cleanup-execution-' + str(index), 'describe-execution', {'executionArn': arn})
        if last['code'] == 'Success' and last['output'].get('status') == 'RUNNING':
            call('cleanup-stop-' + str(index), 'stop-execution', {'executionArn': arn, 'error': 'OwnedProbe.Cleanup'})
    for key in created_machines:
        require('cleanup-list-running-' + key, 'list-executions', {'stateMachineArn': MACHINES[key], 'statusFilter': 'RUNNING', 'maxResults': 100})
        require('cleanup-delete-' + key, 'delete-state-machine', {'stateMachineArn': MACHINES[key]})
    if role_created:
        require('cleanup-delete-role', 'delete-role', {'RoleName': ROLE}, 'iam')
        absent = call('cleanup-role-absence', 'get-role', {'RoleName': ROLE}, 'iam')
        CAP['cleanup']['role_absent'] = absent['code'] == 'NoSuchEntity'
    pending = list(created_machines)
    poll = 0
    while pending and time.monotonic() - cleanup_started < CAP['protocol']['cleanup_wall_seconds']:
